/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 s=f.read_text(); lines=s.splitlines(); page='?'; hits=[]
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m: page=m.group(1)
  if re.search(r'california|governing law|choice of law|applicable law',l,re.I):
   hits.append((page,' '.join(lines[max(0,i-1):i+4])))
 print('\\nFILE',f.name)
 for p,t in hits: print('PAGE',p,t)
 if not hits: print('NO HITS; ending:',s[-4500:])
PY"

