from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
 s=f.read_text().replace('\\xa0',' '); lines=s.splitlines(); page='?'; out=[]
 for i,l in enumerate(lines):
  m=re.search(r'--- page (\\d+) ---',l)
  if m:page=m.group(1)
  if re.search(r'governed by|governing law|choice of law|applicable law',l,re.I):
   t=' '.join(lines[i:i+4])
   if re.search(r'govern|choice',t,re.I):out.append((page,t[:650]))
 print(f.name.removesuffix('.txt'))
 for p,t in out:print(p,t)
 if not out: print('NO governing clause hits')
PY"

